contracts/AnaguEscrow.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IERC721} from "@openzeppelin/contracts/token/ERC721/IERC721.sol";

interface IApprovedEscrowTitle {
    function transferForApprovedEscrow(uint256 tokenId, address buyer) external;
}

contract AnaguEscrow is AccessControl, Pausable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    bytes32 public constant REGISTRAR_ROLE = keccak256("REGISTRAR_ROLE");
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    uint16 public constant COMMISSION_BPS = 200;
    uint16 public constant BPS_DENOMINATOR = 10_000;

    IERC20 public immutable anaguToken;
    IERC721 public immutable titleContract;
    IApprovedEscrowTitle public immutable approvedTitleContract;
    address public immutable treasury;

    enum EscrowStatus {
        None,
        Listed,
        Funded,
        Settled,
        Cancelled,
        Refunded,
        Expired
    }

    struct EscrowListing {
        uint256 tokenId;
        address seller;
        address buyer;
        uint256 price;
        uint64 expiresAt;
        EscrowStatus status;
    }

    mapping(uint256 => EscrowListing) private _escrows;

    event ParcelListed(
        uint256 indexed tokenId,
        address indexed seller,
        uint256 price,
        uint64 expiresAt
    );
    event EscrowFunded(uint256 indexed tokenId, address indexed buyer, uint256 amount);
    event EscrowSettled(
        uint256 indexed tokenId,
        address indexed seller,
        address indexed buyer,
        uint256 sellerAmount,
        uint256 treasuryAmount
    );
    event EscrowCancelled(uint256 indexed tokenId, address indexed caller);
    event EscrowRefunded(uint256 indexed tokenId, address indexed buyer, uint256 amount);
    event EscrowExpired(uint256 indexed tokenId, address indexed buyer, uint256 amount);

    error ZeroAddress();
    error InvalidPrice();
    error InvalidExpiry();
    error ListingNotAvailable(uint256 tokenId);
    error NotSeller(address caller, address seller);
    error NotBuyer(address caller, address buyer);
    error BuyerCannotBeSeller();
    error EscrowNotFunded(uint256 tokenId);
    error EscrowAlreadyFunded(uint256 tokenId);
    error EscrowNotExpired(uint256 tokenId, uint64 expiresAt);
    error IncorrectPaymentAmount(uint256 expected, uint256 provided);
    error NFTNotOwnedBySeller(uint256 tokenId, address seller);

    constructor(
        address admin,
        address registrar,
        address treasuryAddress,
        address anaguTokenAddress,
        address titleContractAddress
    ) {
        if (
            admin == address(0) ||
            registrar == address(0) ||
            treasuryAddress == address(0) ||
            anaguTokenAddress == address(0) ||
            titleContractAddress == address(0)
        ) revert ZeroAddress();

        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(REGISTRAR_ROLE, registrar);
        _grantRole(PAUSER_ROLE, admin);

        treasury = treasuryAddress;
        anaguToken = IERC20(anaguTokenAddress);
        titleContract = IERC721(titleContractAddress);
        approvedTitleContract = IApprovedEscrowTitle(titleContractAddress);
    }

    function listParcel(uint256 tokenId, uint256 price, uint64 expiresAt) external whenNotPaused {
        if (price == 0) revert InvalidPrice();
        if (expiresAt <= block.timestamp) revert InvalidExpiry();
        if (titleContract.ownerOf(tokenId) != msg.sender) {
            revert NFTNotOwnedBySeller(tokenId, msg.sender);
        }

        EscrowListing storage existing = _escrows[tokenId];
        if (existing.status == EscrowStatus.Listed || existing.status == EscrowStatus.Funded) {
            revert ListingNotAvailable(tokenId);
        }

        _escrows[tokenId] = EscrowListing({
            tokenId: tokenId,
            seller: msg.sender,
            buyer: address(0),
            price: price,
            expiresAt: expiresAt,
            status: EscrowStatus.Listed
        });

        emit ParcelListed(tokenId, msg.sender, price, expiresAt);
    }

    function fundEscrow(uint256 tokenId) external whenNotPaused nonReentrant {
        EscrowListing storage listing = _escrows[tokenId];
        if (listing.status != EscrowStatus.Listed) revert ListingNotAvailable(tokenId);
        if (block.timestamp >= listing.expiresAt) revert EscrowNotExpired(tokenId, listing.expiresAt);
        if (msg.sender == listing.seller) revert BuyerCannotBeSeller();
        if (titleContract.ownerOf(tokenId) != listing.seller) {
            revert NFTNotOwnedBySeller(tokenId, listing.seller);
        }

        uint256 allowance = anaguToken.allowance(msg.sender, address(this));
        if (allowance < listing.price) revert IncorrectPaymentAmount(listing.price, allowance);

        anaguToken.safeTransferFrom(msg.sender, address(this), listing.price);
        listing.buyer = msg.sender;
        listing.status = EscrowStatus.Funded;

        emit EscrowFunded(tokenId, msg.sender, listing.price);
    }

    function settleSale(uint256 tokenId) external whenNotPaused nonReentrant {
        EscrowListing storage listing = _escrows[tokenId];
        if (listing.status != EscrowStatus.Funded) revert EscrowNotFunded(tokenId);
        if (msg.sender != listing.seller) revert NotSeller(msg.sender, listing.seller);
        if (titleContract.ownerOf(tokenId) != listing.seller) {
            revert NFTNotOwnedBySeller(tokenId, listing.seller);
        }

        uint256 commission = (listing.price * COMMISSION_BPS) / BPS_DENOMINATOR;
        uint256 sellerAmount = listing.price - commission;
        address seller = listing.seller;
        address buyer = listing.buyer;

        listing.status = EscrowStatus.Settled;
        approvedTitleContract.transferForApprovedEscrow(tokenId, buyer);

        anaguToken.safeTransfer(seller, sellerAmount);
        if (commission > 0) {
            anaguToken.safeTransfer(treasury, commission);
        }

        emit EscrowSettled(tokenId, seller, buyer, sellerAmount, commission);
    }

    function cancelListing(uint256 tokenId) external whenNotPaused nonReentrant {
        EscrowListing storage listing = _escrows[tokenId];
        if (listing.status != EscrowStatus.Listed) revert ListingNotAvailable(tokenId);
        if (msg.sender != listing.seller && !hasRole(REGISTRAR_ROLE, msg.sender)) {
            revert NotSeller(msg.sender, listing.seller);
        }

        listing.status = EscrowStatus.Cancelled;
        emit EscrowCancelled(tokenId, msg.sender);
    }

    function refundEscrow(uint256 tokenId) external whenNotPaused nonReentrant {
        EscrowListing storage listing = _escrows[tokenId];
        if (listing.status != EscrowStatus.Funded) revert EscrowNotFunded(tokenId);

        bool canRefund =
            msg.sender == listing.buyer ||
            hasRole(REGISTRAR_ROLE, msg.sender);
        if (!canRefund) revert NotBuyer(msg.sender, listing.buyer);
        if (block.timestamp < listing.expiresAt) {
            revert EscrowNotExpired(tokenId, listing.expiresAt);
        }

        listing.status = EscrowStatus.Expired;
        anaguToken.safeTransfer(listing.buyer, listing.price);
        emit EscrowExpired(tokenId, listing.buyer, listing.price);
    }

    function refundFundedEscrow(uint256 tokenId) external onlyRole(REGISTRAR_ROLE) whenNotPaused nonReentrant {
        EscrowListing storage listing = _escrows[tokenId];
        if (listing.status != EscrowStatus.Funded) revert EscrowNotFunded(tokenId);

        address buyer = listing.buyer;
        listing.status = EscrowStatus.Refunded;
        anaguToken.safeTransfer(buyer, listing.price);
        emit EscrowRefunded(tokenId, buyer, listing.price);
    }

    function getEscrow(uint256 tokenId) external view returns (EscrowListing memory) {
        return _escrows[tokenId];
    }

    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
    }
}

contracts/AnaguLandTitle.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {ERC721} from "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import {ERC721URIStorage} from "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";
import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title AnaguLandTitle
 * @notice Academic prototype ERC-721 Land Title & Regulated Polygon Escrow Marketplace.
 * @dev Non-bypassable registry controls:
 *   - Only REGISTRAR_ROLE can mint titles; sellers settle funded marketplace sales.
 *   - Direct owner-to-owner transferFrom / safeTransferFrom calls are blocked.
 *   - Only GOVERNOR_ROLE can revoke titles under statutory grounds, permanently blocking reuse.
 */
contract AnaguLandTitle is ERC721, ERC721URIStorage, AccessControl, ReentrancyGuard {
    bytes32 public constant REGISTRAR_ROLE = keccak256("REGISTRAR_ROLE");
    bytes32 public constant GOVERNOR_ROLE = keccak256("GOVERNOR_ROLE");
    bytes32 public constant ESCROW_ROLE = keccak256("ESCROW_ROLE");

    enum TitleStatus {
        Active,
        Revoked
    }

    enum RevocationGround {
        None,
        OverridingPublicInterest,
        BreachOfStatutoryCondition
    }

    struct TitleRecord {
        uint256 tokenId;
        string parcelCode;
        string applicationRef;
        string metadataUri;
        uint256 issuedAt;
        address issuedBy;
        TitleStatus status;
        RevocationGround revocationGround;
        string revocationReason;
        uint256 revokedAt;
        address revokedBy;
    }

    struct TransferHistoryEntry {
        address from;
        address to;
        uint256 priceWei;
        uint256 timestamp;
        string transferType;
    }

    struct SaleListing {
        uint256 tokenId;
        address seller;
        uint256 priceWei;
        address buyer;
        uint256 escrowFundedWei;
        bool isListed;
        bool escrowFunded;
    }

    uint256 private _nextTokenId = 1;
    bool private _settlementAuthorized = false;

    mapping(uint256 => TitleRecord) private _titles;
    mapping(uint256 => TransferHistoryEntry[]) private _transferHistory;
    mapping(uint256 => SaleListing) private _listings;
    mapping(bytes32 => bool) private _parcelCodeUsed;
    mapping(bytes32 => bool) private _applicationRefUsed;

    error TransferBlockedByRegistryRule(uint256 tokenId);
    error TitleIsRevoked(uint256 tokenId);
    error TitleNotFound(uint256 tokenId);
    error ParcelAlreadyTitled(string parcelCode);
    error ApplicationAlreadyTitled(string applicationRef);
    error InvalidRevocationGround();
    error RevocationReasonTooShort();
    error NotTitleOwner(uint256 tokenId, address caller);
    error InvalidListingPrice();
    error ListingNotActive(uint256 tokenId);
    error EscrowAlreadyFunded(uint256 tokenId);
    error EscrowNotFunded(uint256 tokenId);
    error IncorrectPaymentAmount(uint256 expected, uint256 provided);
    error BuyerCannotBeSeller();
    error NotListingSeller(address caller, address seller);

    event TitleIssued(
        uint256 indexed tokenId,
        address indexed owner,
        string parcelCode,
        string applicationRef,
        string metadataUri,
        address indexed issuedBy
    );

    event TitleRevoked(
        uint256 indexed tokenId,
        RevocationGround indexed ground,
        string reason,
        address indexed revokedBy,
        uint256 revokedAt
    );

    event ParcelListed(uint256 indexed tokenId, address indexed seller, uint256 priceWei);
    event ListingCancelled(uint256 indexed tokenId, address indexed cancelledBy);
    event EscrowFunded(uint256 indexed tokenId, address indexed buyer, uint256 amountWei);
    event SaleSettled(
        uint256 indexed tokenId,
        address indexed seller,
        address indexed buyer,
        uint256 priceWei
    );
    event EscrowRefunded(uint256 indexed tokenId, address indexed buyer, uint256 amountWei);

    constructor(address initialAdmin, address initialRegistrar, address initialGovernor)
        ERC721("ANAGU Digital Land Title", "ANAGU")
    {
        _grantRole(DEFAULT_ADMIN_ROLE, initialAdmin);
        _grantRole(REGISTRAR_ROLE, initialRegistrar);
        _grantRole(GOVERNOR_ROLE, initialGovernor);
    }

    function issueTitle(
        address to,
        string calldata parcelCode,
        string calldata applicationRef,
        string calldata metadataUri
    ) external onlyRole(REGISTRAR_ROLE) returns (uint256) {
        require(to != address(0), "Recipient wallet cannot be zero address");
        require(bytes(parcelCode).length > 0, "Parcel code is required");
        require(bytes(applicationRef).length > 0, "Application reference is required");

        bytes32 parcelKey = keccak256(bytes(parcelCode));
        bytes32 appKey = keccak256(bytes(applicationRef));
        if (_parcelCodeUsed[parcelKey]) revert ParcelAlreadyTitled(parcelCode);
        if (_applicationRefUsed[appKey]) revert ApplicationAlreadyTitled(applicationRef);

        uint256 tokenId = _nextTokenId++;
        _parcelCodeUsed[parcelKey] = true;
        _applicationRefUsed[appKey] = true;

        _safeMint(to, tokenId);
        _setTokenURI(tokenId, metadataUri);

        _titles[tokenId] = TitleRecord({
            tokenId: tokenId,
            parcelCode: parcelCode,
            applicationRef: applicationRef,
            metadataUri: metadataUri,
            issuedAt: block.timestamp,
            issuedBy: msg.sender,
            status: TitleStatus.Active,
            revocationGround: RevocationGround.None,
            revocationReason: "",
            revokedAt: 0,
            revokedBy: address(0)
        });

        _transferHistory[tokenId].push(
            TransferHistoryEntry({
                from: address(0),
                to: to,
                priceWei: 0,
                timestamp: block.timestamp,
                transferType: "MINT_ISSUANCE"
            })
        );

        emit TitleIssued(tokenId, to, parcelCode, applicationRef, metadataUri, msg.sender);
        return tokenId;
    }

    function revokeTitle(
        uint256 tokenId,
        RevocationGround ground,
        string calldata reason
    ) external onlyRole(GOVERNOR_ROLE) {
        if (_ownerOf(tokenId) == address(0)) revert TitleNotFound(tokenId);
        TitleRecord storage title = _titles[tokenId];
        if (title.status == TitleStatus.Revoked) revert TitleIsRevoked(tokenId);
        if (
            ground != RevocationGround.OverridingPublicInterest &&
            ground != RevocationGround.BreachOfStatutoryCondition
        ) {
            revert InvalidRevocationGround();
        }
        if (bytes(reason).length < 10) revert RevocationReasonTooShort();

        title.status = TitleStatus.Revoked;
        title.revocationGround = ground;
        title.revocationReason = reason;
        title.revokedAt = block.timestamp;
        title.revokedBy = msg.sender;

        if (_listings[tokenId].isListed) {
            _listings[tokenId].isListed = false;
        }

        emit TitleRevoked(tokenId, ground, reason, msg.sender, block.timestamp);
    }

    function listParcelForSale(uint256 tokenId, uint256 priceWei) external {
        if (_ownerOf(tokenId) == address(0)) revert TitleNotFound(tokenId);
        if (_titles[tokenId].status == TitleStatus.Revoked) revert TitleIsRevoked(tokenId);
        if (ownerOf(tokenId) != msg.sender) revert NotTitleOwner(tokenId, msg.sender);
        if (priceWei == 0) revert InvalidListingPrice();
        if (_listings[tokenId].escrowFunded) revert EscrowAlreadyFunded(tokenId);

        _listings[tokenId] = SaleListing({
            tokenId: tokenId,
            seller: msg.sender,
            priceWei: priceWei,
            buyer: address(0),
            escrowFundedWei: 0,
            isListed: true,
            escrowFunded: false
        });

        emit ParcelListed(tokenId, msg.sender, priceWei);
    }

    function cancelListing(uint256 tokenId) external {
        SaleListing storage listing = _listings[tokenId];
        if (!listing.isListed) revert ListingNotActive(tokenId);
        if (listing.escrowFunded) revert EscrowAlreadyFunded(tokenId);
        require(
            listing.seller == msg.sender || hasRole(REGISTRAR_ROLE, msg.sender),
            "Only seller or Registrar can cancel listing"
        );

        delete _listings[tokenId];
        emit ListingCancelled(tokenId, msg.sender);
    }

    function buyListedParcel(uint256 tokenId) external payable nonReentrant {
        if (_ownerOf(tokenId) == address(0)) revert TitleNotFound(tokenId);
        if (_titles[tokenId].status == TitleStatus.Revoked) revert TitleIsRevoked(tokenId);

        SaleListing storage listing = _listings[tokenId];
        if (!listing.isListed) revert ListingNotActive(tokenId);
        if (listing.escrowFunded) revert EscrowAlreadyFunded(tokenId);
        if (msg.sender == listing.seller) revert BuyerCannotBeSeller();
        if (msg.value != listing.priceWei) {
            revert IncorrectPaymentAmount(listing.priceWei, msg.value);
        }

        listing.buyer = msg.sender;
        listing.escrowFundedWei = msg.value;
        listing.escrowFunded = true;

        emit EscrowFunded(tokenId, msg.sender, msg.value);
    }

    function settleApprovedSale(uint256 tokenId) external nonReentrant {
        if (_ownerOf(tokenId) == address(0)) revert TitleNotFound(tokenId);
        if (_titles[tokenId].status == TitleStatus.Revoked) revert TitleIsRevoked(tokenId);

        SaleListing storage listing = _listings[tokenId];
        if (!listing.isListed) revert ListingNotActive(tokenId);
        if (!listing.escrowFunded) revert EscrowNotFunded(tokenId);
        if (msg.sender != listing.seller) {
            revert NotListingSeller(msg.sender, listing.seller);
        }

        address seller = listing.seller;
        address buyer = listing.buyer;
        uint256 amount = listing.escrowFundedWei;

        delete _listings[tokenId];

        _settlementAuthorized = true;
        _transfer(seller, buyer, tokenId);
        _settlementAuthorized = false;

        _transferHistory[tokenId].push(
            TransferHistoryEntry({
                from: seller,
                to: buyer,
                priceWei: amount,
                timestamp: block.timestamp,
                transferType: "REGULATED_ESCROW_SALE"
            })
        );

        (bool sent, ) = payable(seller).call{value: amount}("");
        require(sent, "POL settlement payout to seller failed");

        emit SaleSettled(tokenId, seller, buyer, amount);
    }

    function withdrawEscrowOnRevocation(uint256 tokenId) external nonReentrant {
        SaleListing storage listing = _listings[tokenId];
        if (!listing.escrowFunded) revert EscrowNotFunded(tokenId);
        if (_titles[tokenId].status != TitleStatus.Revoked) {
            revert("Escrow refund only allowed when title is revoked");
        }
        require(
            msg.sender == listing.buyer || hasRole(REGISTRAR_ROLE, msg.sender),
            "Only buyer or Registrar can withdraw escrow"
        );

        address buyer = listing.buyer;
        uint256 refundAmount = listing.escrowFundedWei;
        delete _listings[tokenId];

        (bool refunded, ) = payable(buyer).call{value: refundAmount}("");
        require(refunded, "Escrow refund transfer failed");

        emit EscrowRefunded(tokenId, buyer, refundAmount);
    }

    function transferForApprovedEscrow(uint256 tokenId, address buyer)
        external
        onlyRole(ESCROW_ROLE)
        nonReentrant
    {
        if (_ownerOf(tokenId) == address(0)) revert TitleNotFound(tokenId);
        if (_titles[tokenId].status == TitleStatus.Revoked) revert TitleIsRevoked(tokenId);
        if (buyer == address(0)) revert("Buyer cannot be zero address");

        address seller = ownerOf(tokenId);
        _settlementAuthorized = true;
        _transfer(seller, buyer, tokenId);
        _settlementAuthorized = false;

        _transferHistory[tokenId].push(
            TransferHistoryEntry({
                from: seller,
                to: buyer,
                priceWei: 0,
                timestamp: block.timestamp,
                transferType: "APPROVED_ANAGU_ESCROW_SALE"
            })
        );
    }

    function getTitle(uint256 tokenId) external view returns (TitleRecord memory) {
        if (_ownerOf(tokenId) == address(0)) revert TitleNotFound(tokenId);
        return _titles[tokenId];
    }

    function getListing(uint256 tokenId) external view returns (SaleListing memory) {
        return _listings[tokenId];
    }

    function getTransferHistory(uint256 tokenId)
        external
        view
        returns (TransferHistoryEntry[] memory)
    {
        if (_ownerOf(tokenId) == address(0)) revert TitleNotFound(tokenId);
        return _transferHistory[tokenId];
    }

    function totalTitlesIssued() external view returns (uint256) {
        return _nextTokenId - 1;
    }

    function _update(
        address to,
        uint256 tokenId,
        address auth
    ) internal override(ERC721) returns (address) {
        address from = _ownerOf(tokenId);
        if (from != address(0)) {
            if (_titles[tokenId].status == TitleStatus.Revoked) {
                revert TitleIsRevoked(tokenId);
            }
            if (!_settlementAuthorized) {
                revert TransferBlockedByRegistryRule(tokenId);
            }
        }
        return super._update(to, tokenId, auth);
    }

    function tokenURI(uint256 tokenId)
        public
        view
        override(ERC721, ERC721URIStorage)
        returns (string memory)
    {
        return super.tokenURI(tokenId);
    }

    function supportsInterface(bytes4 interfaceId)
        public
        view
        override(ERC721, ERC721URIStorage, AccessControl)
        returns (bool)
    {
        return super.supportsInterface(interfaceId);
    }
}

contracts/AnaguPayment.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {AccessControl} from "@openzeppelin/contracts/access/AccessControl.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {ECDSA} from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import {MessageHashUtils} from "@openzeppelin/contracts/utils/cryptography/MessageHashUtils.sol";

/**
 * @title AnaguPayment
 * @notice Native ETH registration fee payment contract for the Anagu Land Administration Platform.
 * @dev Scope & Security Invariants:
 *   - Collects ONLY land registration fees in native ETH via payable functions.
 *   - Payment NEVER grants land ownership, title approval, or NFT issuance.
 *   - Prevents duplicate payments per unique registration reference.
 *   - Supports configurable fee quotes (backend ECDSA-signed expiring quotes or admin-configured fees).
 *   - Enforces Pausable emergency stop, ReentrancyGuard, and role-restricted treasury withdrawals.
 */
contract AnaguPayment is AccessControl, Pausable, ReentrancyGuard {
    using ECDSA for bytes32;
    using MessageHashUtils for bytes32;

    bytes32 public constant FEE_ADMIN_ROLE = keccak256("FEE_ADMIN_ROLE");
    bytes32 public constant TREASURY_ROLE = keccak256("TREASURY_ROLE");
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");

    struct PaymentRecord {
        string registrationReference;
        bytes32 quoteId;
        address payer;
        uint256 amountWei;
        uint256 paidAt;
        bool paid;
    }

    /// @notice Configurable fallback fee in wei (never hardcoded to an invented statutory NGN fee).
    uint256 public configurableFeeWei;

    /// @notice Optional off-chain quote signer address authorized to sign NGN->ETH expiring quotes.
    address public quoteSigner;

    /// @notice Tracks per-registration payment records keyed by keccak256(bytes(registrationReference)).
    mapping(bytes32 => PaymentRecord) private _paymentsByRefHash;

    /// @notice Optional on-chain quoted fees keyed by registration reference hash.
    mapping(bytes32 => uint256) public quotedFeeWeiByRefHash;

    /// @notice Prevents replay of signed off-chain payment quotes.
    mapping(bytes32 => bool) public usedQuoteIds;

    /// @notice Ordered list of paid registration reference hashes for audit enumeration.
    bytes32[] private _paidRefHashes;

    event PaymentReceived(
        bytes32 indexed regRefHash,
        string registrationReference,
        bytes32 indexed quoteId,
        address indexed payer,
        uint256 amountWei,
        uint256 paidAt
    );

    event ConfigurableFeeUpdated(uint256 previousFeeWei, uint256 newFeeWei, address indexed updatedBy);
    event RegistrationFeeQuoted(
        bytes32 indexed regRefHash,
        string registrationReference,
        uint256 requiredAmountWei,
        address indexed quotedBy
    );
    event QuoteSignerUpdated(address indexed previousSigner, address indexed newSigner, address indexed updatedBy);
    event FundsWithdrawn(address indexed recipient, uint256 amountWei, address indexed withdrawnBy);

    error EmptyRegistrationReference();
    error DuplicateRegistrationPayment(string registrationReference);
    error FeeNotConfigured();
    error InvalidPaymentAmount(uint256 expectedWei, uint256 sentWei);
    error QuoteExpired(uint64 expiresAt, uint256 currentTimestamp);
    error QuoteAlreadyUsed(bytes32 quoteId);
    error QuoteSignerNotSet();
    error InvalidQuoteSignature();
    error ZeroAddressNotAllowed();
    error ZeroWithdrawalAmount();
    error InsufficientContractBalance(uint256 requestedWei, uint256 availableWei);
    error WithdrawalTransferFailed();
    error DirectEthTransferNotAllowed();

    constructor(address admin, address initialQuoteSigner, uint256 initialConfigurableFeeWei) {
        if (admin == address(0)) revert ZeroAddressNotAllowed();

        _grantRole(DEFAULT_ADMIN_ROLE, admin);
        _grantRole(FEE_ADMIN_ROLE, admin);
        _grantRole(TREASURY_ROLE, admin);
        _grantRole(PAUSER_ROLE, admin);

        quoteSigner = initialQuoteSigner;
        configurableFeeWei = initialConfigurableFeeWei;

        emit QuoteSignerUpdated(address(0), initialQuoteSigner, admin);
        emit ConfigurableFeeUpdated(0, initialConfigurableFeeWei, admin);
    }

    /**
     * @notice Pay a registration fee using an off-chain backend-signed NGN->ETH expiring quote.
     * @param registrationReference Unique application reference (e.g. "ANG-APP-2026-0009").
     * @param quoteId Unique 32-byte quote identifier generated by the backend.
     * @param requiredAmountWei Exact native ETH amount in wei computed from NGN fee & exchange rate.
     * @param expiresAt Unix timestamp after which the quote expires.
     * @param signature EIP-191 signature from `quoteSigner`.
     */
    function payWithQuote(
        string calldata registrationReference,
        bytes32 quoteId,
        uint256 requiredAmountWei,
        uint64 expiresAt,
        bytes calldata signature
    ) external payable whenNotPaused nonReentrant {
        if (bytes(registrationReference).length == 0) revert EmptyRegistrationReference();
        if (quoteSigner == address(0)) revert QuoteSignerNotSet();
        if (requiredAmountWei == 0) revert FeeNotConfigured();
        if (block.timestamp > expiresAt) revert QuoteExpired(expiresAt, block.timestamp);
        if (usedQuoteIds[quoteId]) revert QuoteAlreadyUsed(quoteId);

        bytes32 regRefHash = keccak256(bytes(registrationReference));
        if (_paymentsByRefHash[regRefHash].paid) {
            revert DuplicateRegistrationPayment(registrationReference);
        }

        bytes32 digest = keccak256(
            abi.encodePacked(
                block.chainid,
                address(this),
                regRefHash,
                quoteId,
                requiredAmountWei,
                expiresAt
            )
        ).toEthSignedMessageHash();

        address recovered = digest.recover(signature);
        if (recovered != quoteSigner) revert InvalidQuoteSignature();

        if (msg.value != requiredAmountWei) {
            revert InvalidPaymentAmount(requiredAmountWei, msg.value);
        }

        usedQuoteIds[quoteId] = true;
        _recordPayment(regRefHash, registrationReference, quoteId, msg.sender, msg.value);
    }

    /**
     * @notice Pay the registration fee configured on-chain for a registration reference or global configurable fee.
     * @param registrationReference Unique application reference (e.g. "ANG-APP-2026-0009").
     */
    function payRegistrationFee(string calldata registrationReference)
        external
        payable
        whenNotPaused
        nonReentrant
    {
        if (bytes(registrationReference).length == 0) revert EmptyRegistrationReference();

        bytes32 regRefHash = keccak256(bytes(registrationReference));
        if (_paymentsByRefHash[regRefHash].paid) {
            revert DuplicateRegistrationPayment(registrationReference);
        }

        uint256 expectedWei = quotedFeeWeiByRefHash[regRefHash];
        if (expectedWei == 0) {
            expectedWei = configurableFeeWei;
        }
        if (expectedWei == 0) revert FeeNotConfigured();
        if (msg.value != expectedWei) {
            revert InvalidPaymentAmount(expectedWei, msg.value);
        }

        _recordPayment(regRefHash, registrationReference, bytes32(0), msg.sender, msg.value);
    }

    function _recordPayment(
        bytes32 regRefHash,
        string calldata registrationReference,
        bytes32 quoteId,
        address payer,
        uint256 amountWei
    ) internal {
        _paymentsByRefHash[regRefHash] = PaymentRecord({
            registrationReference: registrationReference,
            quoteId: quoteId,
            payer: payer,
            amountWei: amountWei,
            paidAt: block.timestamp,
            paid: true
        });
        _paidRefHashes.push(regRefHash);

        emit PaymentReceived(
            regRefHash,
            registrationReference,
            quoteId,
            payer,
            amountWei,
            block.timestamp
        );
    }

    function setConfigurableFeeWei(uint256 newFeeWei) external onlyRole(FEE_ADMIN_ROLE) {
        uint256 prev = configurableFeeWei;
        configurableFeeWei = newFeeWei;
        emit ConfigurableFeeUpdated(prev, newFeeWei, msg.sender);
    }

    function setRegistrationQuoteFee(string calldata registrationReference, uint256 requiredAmountWei)
        external
        onlyRole(FEE_ADMIN_ROLE)
    {
        if (bytes(registrationReference).length == 0) revert EmptyRegistrationReference();
        bytes32 regRefHash = keccak256(bytes(registrationReference));
        quotedFeeWeiByRefHash[regRefHash] = requiredAmountWei;
        emit RegistrationFeeQuoted(regRefHash, registrationReference, requiredAmountWei, msg.sender);
    }

    function setQuoteSigner(address newQuoteSigner) external onlyRole(DEFAULT_ADMIN_ROLE) {
        address prev = quoteSigner;
        quoteSigner = newQuoteSigner;
        emit QuoteSignerUpdated(prev, newQuoteSigner, msg.sender);
    }

    function pause() external onlyRole(PAUSER_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(PAUSER_ROLE) {
        _unpause();
    }

    function withdraw(address payable recipient, uint256 amountWei)
        external
        onlyRole(TREASURY_ROLE)
        nonReentrant
    {
        if (recipient == address(0)) revert ZeroAddressNotAllowed();
        if (amountWei == 0) revert ZeroWithdrawalAmount();
        uint256 balance = address(this).balance;
        if (amountWei > balance) revert InsufficientContractBalance(amountWei, balance);

        (bool ok, ) = recipient.call{value: amountWei}("");
        if (!ok) revert WithdrawalTransferFailed();

        emit FundsWithdrawn(recipient, amountWei, msg.sender);
    }

    function getPaymentByReference(string calldata registrationReference)
        external
        view
        returns (PaymentRecord memory)
    {
        return _paymentsByRefHash[keccak256(bytes(registrationReference))];
    }

    function hasPaid(string calldata registrationReference) external view returns (bool) {
        return _paymentsByRefHash[keccak256(bytes(registrationReference))].paid;
    }

    function totalPaymentsCount() external view returns (uint256) {
        return _paidRefHashes.length;
    }

    receive() external payable {
        revert DirectEthTransferNotAllowed();
    }

    fallback() external payable {
        revert DirectEthTransferNotAllowed();
    }
}

contracts/AnaguToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";

contract AnaguToken is ERC20 {
    uint256 public constant MAX_SUPPLY = 100_000_000 * 10 ** 18;

    error ZeroTreasuryAddress();

    constructor(address treasury) ERC20("ANAGU Token", "ANAGU") {
        if (treasury == address(0)) revert ZeroTreasuryAddress();
        _mint(treasury, MAX_SUPPLY);
    }
}

